    if ((wheel_axes_body == NULL) || (desired_body_torque_nm == NULL) || 
        (wheel_torque_limit_nm == NULL) || (wheel_torque_nm == NULL) || 
        (achieved_body_torque_nm == NULL) || (saturation_mask == NULL)) {
        return ADCS_E_NULL;
    }

    size_t i;
    double limit_val;

    // Check finiteness of all input vectors and scalars
    for (i = 0; i < 3; ++i) {
        if (!adcs_is_finite_vec3(&wheel_axes_body[i])) {
            return ADCS_E_RANGE;
        }
    }
    if (!adcs_is_finite_vec3(desired_body_torque_nm)) {
        return ADCS_E_RANGE;
    }
    for (i = 0; i < 3; ++i) {
        if (!isfinite(wheel_torque_limit_nm[i]) || wheel_torque_limit_nm[i] < 0.0) {
            return ADCS_E_RANGE;
        }
    }

    // Validate the complete triad: mutual orthogonality within 1e-10 tolerance
    // Also ensure axes are not zero vectors (required for unit vectors)
    adcs_vec3_t ax[3];
    for (i = 0; i < 3; ++i) {
        ax[i] = wheel_axes_body[i];
        if (adcs_vec3_norm(&ax[i]) <= 1.0e-10) {
            return ADCS_E_RANGE;
        }
    }

    // Check pairwise orthogonality
    if (fabs(adcs_vec3_dot(&ax[0], &ax[1])) > 1.0e-10) return ADCS_E_RANGE;
    if (fabs(adcs_vec3_dot(&ax[0], &ax[2])) > 1.0e-10) return ADCS_E_RANGE;
    if (fabs(adcs_vec3_dot(&ax[1], &ax[2])) > 1.0e-10) return ADCS_E_RANGE;

    // Initialize outputs
    *saturation_mask = 0U;
    adcs_vec3_t achieved_body_torque = {0.0, 0.0, 0.0};
    adcs_vec3_t scaled_ax;

    // Allocate, clamp, and reconstruct
    for (i = 0; i < 3; ++i) {
        limit_val = wheel_torque_limit_nm[i];

        // Unconstrained command: u_i = - a_i . tau_desired
        double u = -adcs_vec3_dot(&ax[i], desired_body_torque_nm);

        // Clamp each u_i independently
        if (u > limit_val) {
            u = limit_val;
            *saturation_mask |= (unint32)(1U << i);
        } else if (u < -limit_val) {
            u = -limit_val;
            *saturation_mask |= (unint32)(1U << i);
        }

        // Store wheel torque
        wheel_torque_nm[i] = u;

        // Achieved spacecraft torque is -sum u_i a_i
        // Add contribution of this wheel: -u * axis
        scaled_ax = adcs_vec3_scale(&ax[i], -u);
        achieved_body_torque = adcs_vec3_add(&achieved_body_torque, &scaled_ax);
